protocol "All T1 Modalities" {
    id: "00000000-0000-0000-0000-000000000001"
    description: "All eight T1 modalities"
    author: "test"
    version: "1.0"
    tags: []
    duration: 30m

    pbm_transcranial {
        wavelength: "808nm"
        irradiance: 302mW_cm2
        frequency: 20Hz
        duty_cycle: 25%
        zones: ["All"]
