    pbm_intranasal {
        wavelength: "660nm"
        irradiance: 60mW_cm2
        frequency: 40Hz
        duty_cycle: 25%
    }

    eeg_neurofeedback {
        band: alpha
        channels: all
        closed_loop: true
    }

    bes_tacs {
        frequency: 10Hz
        intensity: 0.8mA
        waveform: sinusoidal
    }

    tdcs {
        intensity: 1.5mA
        electrode_pairs: [["Fp1", "P3"]]
        electrode_area_cm2: 35
        ramp: 30s
    }

    vns_hrv {
        frequency: 25Hz
        intensity: 1.5mA
        hrv_protocol: standalone
        breathing_rate: 6
    }

    audio_entrainment {
        binaural_hz: 40Hz
        noise: pink
        carrier_hz: 440Hz
        volume: 70dB
        eeg_adaptive: true
        bone_conduction_pacer: true
    }

    visual_stimulation {
        frequency: 40Hz
        mode: binocular
        emdr_cadence: 1Hz
        enable_mode_f: false
    }
}

